import{_ as t,c as a,o as r,ae as o}from"./chunks/framework.Cd-3tpCq.js";const p=JSON.parse('{"title":"List Currencies","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"admin-settings-currencies-list","title":"List Currencies","description":"Paginated list of every currency configured in the store.","query":"curl -X GET \\"https://your-domain.com/api/admin/settings/currencies?per_page=10\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\"\\n","response":"{\\n  \\"data\\": [\\n    {\\n      \\"id\\": 1,\\n      \\"code\\": \\"USD\\",\\n      \\"name\\": \\"US Dollar\\",\\n      \\"symbol\\": \\"$\\",\\n      \\"decimal\\": 2,\\n      \\"groupSeparator\\": \\",\\",\\n      \\"decimalSeparator\\": \\".\\",\\n      \\"currencyPosition\\": \\"left\\",\\n      \\"createdAt\\": null,\\n      \\"updatedAt\\": null\\n    }\\n  ],\\n  \\"meta\\": {\\n    \\"currentPage\\": 1,\\n    \\"perPage\\": 10,\\n    \\"lastPage\\": 1,\\n    \\"total\\": 1,\\n    \\"from\\": 1,\\n    \\"to\\": 1\\n  }\\n}\\n"},{"id":"filtered","title":"Filtered + Sorted","description":"Narrow by code, sorted by name ascending. Supplying multiple filters narrows the result (logical AND).","query":"curl -X GET \\"https://your-domain.com/api/admin/settings/currencies?code=USD&sort=name&order=asc&per_page=10\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\"\\n","response":"{\\n  \\"data\\": [\\n    {\\n      \\"id\\": 1,\\n      \\"code\\": \\"USD\\",\\n      \\"name\\": \\"US Dollar\\",\\n      \\"symbol\\": \\"$\\",\\n      \\"decimal\\": 2,\\n      \\"groupSeparator\\": \\",\\",\\n      \\"decimalSeparator\\": \\".\\",\\n      \\"currencyPosition\\": \\"left\\",\\n      \\"createdAt\\": null,\\n      \\"updatedAt\\": null\\n    }\\n  ],\\n  \\"meta\\": {\\n    \\"currentPage\\": 1,\\n    \\"perPage\\": 10,\\n    \\"lastPage\\": 1,\\n    \\"total\\": 1,\\n    \\"from\\": 1,\\n    \\"to\\": 1\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/rest-api/admin/settings/currencies/list.md","filePath":"api/rest-api/admin/settings/currencies/list.md"}'),d={name:"api/rest-api/admin/settings/currencies/list.md"};function n(c,e,i,s,l,u){return r(),a("div",null,e[0]||(e[0]=[o('<h1 id="list-currencies" tabindex="-1">List Currencies <a class="header-anchor" href="#list-currencies" aria-label="Permalink to &quot;List Currencies&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th></tr></thead><tbody><tr><td><code>/api/admin/settings/currencies</code></td><td>GET</td></tr></tbody></table><p>Returns every currency configured in the store in the <code>{ data, meta }</code> envelope. Use it to populate a currency picker, audit which currencies a store supports, or look up a currency&#39;s <code>id</code> before a detail / update / delete call.</p><h2 id="pagination" tabindex="-1">Pagination <a class="header-anchor" href="#pagination" aria-label="Permalink to &quot;Pagination&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>page</code></td><td>Page number, 1-based. Default <code>1</code>.</td></tr><tr><td><code>per_page</code></td><td>Items per page. Default <code>10</code>, max <code>50</code>.</td></tr></tbody></table><h2 id="filters" tabindex="-1">Filters <a class="header-anchor" href="#filters" aria-label="Permalink to &quot;Filters&quot;">​</a></h2><p>Query parameters that narrow the result. Supplying more than one <strong>narrows further</strong> — they combine with logical <strong>AND</strong>. They mirror the admin Currencies datagrid filters.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Match</th><th>Example</th></tr></thead><tbody><tr><td><code>code</code></td><td>Partial (contains).</td><td><code>?code=USD</code></td></tr><tr><td><code>name</code></td><td>Partial (contains).</td><td><code>?name=Dollar</code></td></tr><tr><td><code>symbol</code></td><td>Partial (contains).</td><td><code>?symbol=$</code></td></tr></tbody></table><h2 id="sorting" tabindex="-1">Sorting <a class="header-anchor" href="#sorting" aria-label="Permalink to &quot;Sorting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Values</th></tr></thead><tbody><tr><td><code>sort</code></td><td><code>id</code> (default), <code>code</code>, <code>name</code></td></tr><tr><td><code>order</code></td><td><code>asc</code>, <code>desc</code> (default <code>desc</code>)</td></tr></tbody></table><p>Both the compound form <code>?sort=name-asc</code> and the split form <code>?sort=name&amp;order=asc</code> are accepted.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li><code>symbol</code> and <code>currencyPosition</code> may be <code>null</code> for currencies created without those fields set.</li><li>The seeded default currency (<code>USD</code>) may carry <code>null</code> <code>createdAt</code> / <code>updatedAt</code>.</li></ul>',13)]))}const m=t(d,[["render",n]]);export{p as __pageData,m as default};
